SELECT XX.* ,DECODE(XX.PARCEL_INV_NO,NULL,'','택배송장조회') AS PARCEL_REAL_URL_BUTTON , CASE WHEN XX.IMAGE_KEY_INV IS NOT NULL THEN '/resources/imgs/Btn_RegEnd.gif' ELSE CASE WHEN XX.PARCEL_YN = 'Y' THEN '/resources/imgs/Btn_RegIng.gif' ELSE CASE WHEN XX.AUTO_GR_FLAG = 'Y' AND XX.PROCESS_TYPE = 0 THEN '/resources/imgs/Btn_RegR.gif' WHEN XX.P070000029_YN = 'Y' AND XX.PROCESS_TYPE = 0 THEN '/resources/imgs/Btn_RegR.gif' ELSE '/resources/imgs/Btn_RegIng.gif' END END END AS IMAGE_KEY_INV_CNT FROM( SELECT /*getSellerMpIvDeliveryRecordRegList_v2*/ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01')) AS BUYER_NAME -- 1 구매사 , B.PO_NO -- 2 발주번호 , B.DS_DATE , B.INV_NO -- 4 거래명세서번호 , MIN(B.INVOICE_DATE) AS INVOICE_DATE , MIN(B.INVOICE_DATE) AS INVOICE_DATE_ORG -- 5 납품일 , SUM(C.AGENT_PRICE * B.INV_QTY) AS INV_AMT -- 9 납품금액 , MAX(C.LEGACY_PO_NO) AS LEGACY_PO_NO -- 13 구매사발주번호 , B.BUYER AS BUYER -- 15 , MAX(C.SELLER) AS SELLER -- 21 , MAX(DECODE(C.ACCOUNT_TYPE,'X',DECODE(C.PROCESS_TYPE,'2',C.WAREHOUSE_CODE,F_GET_HIDDEN_BUYER_NAME(C.BUYER, '01')),F_GET_HIDDEN_BUYER_NAME(C.BUYER, '01'))) AS BUYER2 -- 22 , MAX(A.LEGACY_IV_SERIAL) AS LEGACY_IV_SERIAL -- 26 , MAX(A.PARCEL_COM_CODE) AS PARCEL_COM_CODE , MAX(F_GET_CMCD_NAME('C019', A.PARCEL_COM_CODE)) AS PARCEL_COM_NAME , MAX(A.PARCEL_INV_NO) AS PARCEL_INV_NO , MAX(DECODE(G.DOC_TYPE,'S',G.PO_CREATE_DATE,'-')) AS BFRE_STCK_YN , MAX(DECODE(C.PROCESS_TYPE,'2',C.WAREHOUSE_CODE,B.BUYER)) AS TR_BUYER , MAX(E.AUTO_GR_FLAG) AS AUTO_GR_FLAG , MAX(C.PROCESS_TYPE) AS PROCESS_TYPE , MAX(A.IMAGE_KEY_INV) AS IMAGE_KEY_INV , MAX((SELECT DECODE(COUNT(AA.SLG_ID), 0, 'N', 'Y') FROM BNTSLGDEF AA, BNTSLGIMP BB WHERE AA.SLG_ID = BB.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN AA.OPEN_DATE AND AA.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN BB.OPEN_DATE AND BB.CLOSE_DATE AND BB.COM_CODE = B.BUYER AND AA.SLG_ID = 'P07-0000029')) AS P070000029_YN , MAX(NVL(NVL(A.PARCEL_YN, (SELECT PARCEL_YN FROM ICOMPOHD WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND STATUS <> 'D')),'N')) AS PARCEL_YN , MAX(DECODE(NVL((SELECT PARCEL_YN FROM ICOMPOHD WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND STATUS <> 'D'), A.PARCEL_YN), 'Y', '택배배송', '자차배송')) AS PARCEL_TYPE_TEXT , MAX(REPLACE(F.INV_NO_URL,'param',A.PARCEL_INV_NO)) AS PARCEL_REAL_URL , MAX(NVL(A.PARCEL_PRO_STATUS, '자동배송확정 예정')) AS PARCEL_PRO_STATUS ,MAX(F_GET_MIS_BUYER_MNG(C.BUYER, C.PO_NO, C.PO_SEQ)) AS KEP_USER_INFO , CASE WHEN COUNT(*) = 1 THEN MIN(B.DESCRIPTION) ELSE MIN(B.DESCRIPTION) || ' 외 ' || (COUNT(*)-1) || '건' END AS DESCRIPTION_INFO ,MAX(DECODE(C.PROCESS_TYPE, '0', '직납', '2', 'TR(' || (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = NVL((SELECT DELY_TO_CENTER FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT), C.WAREHOUSE_CODE)) || ')' , ' ')) AS PROCESS_TYPE_TEXT FROM ICOMIVHD A , ICOMIVDT B , ICOMPODT C , KEP_BUYER_FLAG E ,(SELECT CODE, TEXT5 AS INV_NO_URL FROM ICOMCOD1 WHERE TYPE = 'C019') F ,ICOMPOHD G WHERE A.AGENT = #{st_com_code} AND C.BUYER = E.COM_CODE(+)
AND A.INV_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND G.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.PARCEL_INV_NO IS NOT NULL
AND A.PARCEL_INV_NO IS NULL
AND A.INV_NO LIKE UPPER('%'||TRIM(#{st_inv_no})||'%')
AND G.DOC_TYPE = #{st_bfre_stck_yn}
AND G.DOC_TYPE != 'S'
AND (A.BUYER = #{st_buyer_code} OR C.WAREHOUSE_CODE = #{st_buyer_code})
AND (C.PO_NO IN
UPPER(#{item})
OR C.LEGACY_PO_NO IN
UPPER(#{item})
)
AND NVL(A.PARCEL_YN, NVL((SELECT PARCEL_YN FROM ICOMPOHD WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND STATUS <> 'D'),'N')) = #{st_parcel_yn}
AND B.DELIVERY_DATE IS NULL --AND (B.DELIVERY_DATE IS NULL OR B.INV_QTY <> B.DELIVERY_QTY) AND A.BUYER = B.BUYER AND A.INV_NO = B.INV_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ = C.PO_SEQ AND A.PARCEL_COM_CODE = F.CODE (+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND G.STATUS != 'D' AND C.BUYER = G.BUYER AND C.PO_NO = G.PO_NO GROUP BY B.BUYER,B.INV_NO,B.DS_DATE,B.PO_NO ORDER BY INVOICE_DATE DESC ,BUYER_NAME , PO_NO )XX WHERE 1=1
AND REPLACE(UPPER(XX.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'

