 C.BUYER AND PO_NO = C.PO_NO AND STATUS <> 'D')),'N')) AS PARCEL_YN , MAX(DECODE(NVL((SELECT PARCEL_YN FROM ICOMPOHD WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND STATUS <> 'D'), A.PARCEL_YN), 'Y', '택배배송', '자차배송')) AS PARCEL_TYPE_TEXT , MAX(REPLACE(F.INV_NO_URL,'param',A.PARCEL_INV_NO)) AS PARCEL_REAL_URL , MAX(NVL(A.PARCEL_PRO_STATUS, '자동배송확정 예정')) AS PARCEL_PRO_STATUS ,MAX(F_GET_MIS_BUYER_MNG(C.BUYER, C.PO_NO, C.PO_SEQ)) AS KEP_USER_INFO , CASE WHEN COUNT(*) = 1 THEN MIN(B.DESCRIPTION) ELSE MIN(B.DESCRIPTION) || ' 외 ' || (COUNT(*)-1) || '건' END AS DESCRIPTION_INFO ,MAX(DECODE(C.PROCESS_TYPE, '0', '직납', '2', 'TR(' || (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = NVL((SELECT DELY_TO_CENTER FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT), C.WAREHOUSE_CODE)) || ')' , ' ')) AS PROCESS_TYPE_TEXT FROM ICOMIVHD A , ICOMIVDT B , ICOMPODT C , KEP_BUYER_FLAG E ,(SELECT CODE, TEXT5 AS INV_NO_URL FROM ICOMCOD1 WHERE TYPE = 'C019') F ,ICOMPOHD G WHERE A.AGENT = #{st_com_code} AND C.BUYER = E.COM_CODE(+)
