UPDATE ICOMIVDT A   
/*updateDeliveryRecordRegIvdt*/
SET 
	  A.DELIVERY_QTY = ( SELECT B.INV_QTY FROM ICOMIVDT B
	  							WHERE   B.BUYER   = #{buyer}
								AND 	B.INV_NO  = #{inv_no}
								AND 	B.INV_SEQ = #{inv_seq}
								AND 	B.STATUS != 'D' )
	, A.DELIVERY_DATE = #{delivery_date} 
	, A.DELIVERY_ADD_DATE = SYSDATE
	, A.DELIVERY_ADD_USER_ID = #{st_user_id}       
WHERE
		A.BUYER   = #{buyer}
	AND A.INV_NO  = #{inv_no}
	AND A.INV_SEQ = #{inv_seq}
	AND A.STATUS != 'D'

