				AND INV_NO  = #{inv_no}
				AND STATUS != 'D'


			/*updateDeliveryRecordParcelRegIvhd*/
 		 	UPDATE ICOMIVHD
			SET	  PARCEL_COM_CODE = #{parcel_com_code}
				, PARCEL_INV_NO 	= #{parcel_inv_no}
				, PARCEL_YN = 'Y'
				, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')	
				, CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
				, PARCEL_PRO_STATUS = NULL
				, PARCEL_ADD_DATE = SYSDATE
				, PARCEL_ADD_USER_ID = #{st_user_id}
			WHERE
					BUYER   = #{buyer}
				AND INV_NO  = #{inv_no}
				AND STATUS != 'D'


			/*updateDeliveryRecordParcelRegIvdt_v3*/
