			WHERE
					BUYER   = #{buyer}
				AND INV_NO  = #{inv_no}
				AND INV_SEQ = #{inv_seq}
				AND STATUS != 'D'


			/*updateDeliveryRecordRegPors*/
 		 	UPDATE	ICOMPORS A    
			SET		A.ADMIN_FLAG2 = DECODE((SELECT COMPLETE_MARK FROM ICOMPODT WHERE BUYER = #{buyer} AND PO_NO = #{po_no} AND PO_SEQ = #{po_seq}), 'Y', 'Y', 'N')
			WHERE	A.BUYER   = #{buyer}
			AND		A.PO_NO   = #{po_no}
			AND		A.PO_SEQ  = #{po_seq}
			AND		A.STATUS != 'D'


