UPDATE ICOMPODT
SET
	GR_QTY = NVL(GR_QTY,0) + #{GR_QTY}
WHERE
		BUYER 	= #{BUYER}
	AND SELLER  = 'KRKORE0001'
	AND PO_NO   = #{PO_NO}
	AND PO_SEQ  = #{PO_SEQ}
	AND STATUS != 'D'


/*updateMasterMpSoSellerWarhsngProcIvhd*/
UPDATE ICOMIVHD 
