/*getSellerMpIvDeliveryRecordRegEndList_v2*/ SELECT X.* FROM( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01'))) AS BUYER_NAME --구매사 , B.PO_NO --발주번호 , B.DS_DATE --납품예정일 , B.INV_NO --거래명세서번호 , MAX(B.DELIVERY_DATE) AS DELIVERY_DATE --납품일 , MAX(C.GR_QTY) AS GR_QTY --입고수량 , MAX(B.BUYER) AS BUYER , MAX(C.SELLER) AS SELLER , MIN(B.INVOICE_DATE) AS INVOICE_DATE , MAX(A.LEGACY_IV_SERIAL) AS LEGACY_IV_SERIAL , MAX(DECODE(E.DOC_TYPE,'S',E.PO_CREATE_DATE,'-')) AS BFRE_STCK_YN , MAX(F_GET_CMCD_NAME('C019', A.PARCEL_COM_CODE)) AS PARCEL_COM_NAME , MAX(A.PARCEL_INV_NO) AS PARCEL_INV_NO , MAX(DECODE(C.PROCESS_TYPE,'2',C.WAREHOUSE_CODE,B.BUYER)) AS TR_BUYER , MAX(F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01')) AS BUYER2 , MAX(A.IMAGE_KEY_SIGN) AS IMAGE_KEY_SIGN , MAX(A.IMAGE_KEY_INV) AS IMAGE_KEY_INV , MAX(C.PROCESS_TYPE) AS PROCESS_TYPE , MAX(A.PARCEL_PRO_STATUS) AS PARCEL_PRO_STATUS , MAX(DECODE(NVL(A.PARCEL_YN, 'N'), 'N', '자차', '택배')) AS PARCEL_YN_TEXT , MAX(REPLACE(INV_NO_URL,'param',PARCEL_INV_NO)) AS PARCEL_REAL_URL , SUM(C.AGENT_PRICE * B.INV_QTY) AS INV_AMT ,MAX(F_GET_MIS_BUYER_MNG(C.BUYER, C.PO_NO, C.PO_SEQ)) AS KEP_USER_INFO ,MAX(DECODE(A.PARCEL_INV_NO,NULL,'','택배송장조회')) AS PARCEL_REAL_URL_BUTTON ,MAX(DECODE((SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = A.IMAGE_KEY_INV), 0, '', '첨부('||(SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = A.IMAGE_KEY_INV)||')')) AS IMAGE_KEY_INV_CNT , CASE WHEN COUNT(*) = 1 THEN MIN(B.DESCRIPTION) ELSE MIN(B.DESCRIPTION) || ' 외 ' || (COUNT(*)-1) || '건' END AS DESCRIPTION_INFO ,MAX(DECODE(C.PROCESS_TYPE, '0', '직납', '2', 'TR(' || (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = NVL((SELECT DELY_TO_CENTER FROM SUPLINFO2 WHERE SUPPLIER = E.AGENT), C.WAREHOUSE_CODE)) || ')' , ' ')) AS PROCESS_TYPE_TEXT FROM ICOMIVHD A , ICOMIVDT B , ICOMPODT C,ICOMPOHD E, (SELECT CODE, TEXT5 AS INV_NO_URL FROM ICOMCOD1 WHERE TYPE = 'C019') D WHERE A.AGENT = #{st_com_code} AND A.INV_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND A.INV_NO LIKE UPPER('%'||TRIM(#{st_inv_no})||'%')
AND (C.PO_NO IN
UPPER(#{item})
OR C.LEGACY_PO_NO IN
UPPER(#{item})
)
AND E.DOC_TYPE = #{st_bfre_stck_yn}
AND E.DOC_TYPE != 'S'
AND A.PARCEL_INV_NO LIKE '%'||TRIM(#{st_parcel_inv_no})||'%'
AND A.PARCEL_YN = #{st_parcel_type}
AND A.PARCEL_COM_CODE = #{st_parcel_com_code}
AND A.IMAGE_KEY_INV IS NOT NULL
AND A.IMAGE_KEY_INV IS NULL
AND B.DELIVERY_DATE IS NOT NULL AND A.BUYER = B.BUYER AND A.INV_NO = B.INV_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ = C.PO_SEQ AND C.BUYER = E.BUYER AND C.PO_NO = E.PO_NO AND A.PARCEL_COM_CODE = D.CODE (+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' GROUP BY B.INV_NO,B.DS_DATE,B.PO_NO ORDER BY INVOICE_DATE DESC,DELIVERY_DATE DESC , BUYER_NAME, PO_NO )X WHERE 1=1
AND REPLACE(UPPER(X.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'

/*getSellerMpIvDeliveryRecordRegEndList_v3*/ SELECT X.* FROM( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01'))) AS BUYER_NAME --구매사 , B.PO_NO --발주번호 , B.DS_DATE --납품예정일 , B.INV_NO --거래명세서번호 , MAX(B.DELIVERY_DATE) AS DELIVERY_DATE --납품일 , MAX(C.GR_QTY) AS GR_QTY --입고수량 , MAX(B.BUYER) AS BUYER , MAX(C.SELLER) AS SELLER , MIN(B.INVOICE_DATE) AS INVOICE_DATE , MAX(A.LEGACY_IV_SERIAL) AS LEGACY_IV_SERIAL , MAX(DECODE(E.DOC_TYPE,'S',E.PO_CREATE_DATE,'-')) AS BFRE_STCK_YN , MAX(F_GET_CMCD_NAME('C019', A.PARCEL_COM_CODE)) AS PARCEL_COM_NAME , MAX(A.PARCEL_INV_NO) AS PARCEL_INV_NO , MAX(DECODE(C.PROCESS_TYPE,'2',C.WAREHOUSE_CODE,B.BUYER)) AS TR_BUYER , MAX(F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01')) AS BUYER2 , MAX(A.IMAGE_KEY_SIGN) AS IMAGE_KEY_SIGN , MAX(A.IMAGE_KEY_INV) AS IMAGE_KEY_INV , MAX(C.PROCESS_TYPE) AS PROCESS_TYPE , MAX(A.PARCEL_PRO_STATUS) AS PARCEL_PRO_STATUS , MAX(DECODE(NVL(A.PARCEL_YN, 'N'), 'N', '자차', '택배')) AS PARCEL_YN_TEXT , MAX(REPLACE(INV_NO_URL,'param',PARCEL_INV_NO)) AS PARCEL_REAL_URL , SUM(C.AGENT_PRICE * B.INV_QTY) AS INV_AMT ,MAX(F_GET_MIS_BUYER_MNG(C.BUYER, C.PO_NO, C.PO_SEQ)) AS KEP_USER_INFO ,MAX(DECODE(A.PARCEL_INV_NO,NULL,'','택배송장조회')) AS PARCEL_REAL_URL_BUTTON ,MAX(DECODE((SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = A.IMAGE_KEY_INV), 0, '', '첨부('||(SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = A.IMAGE_KEY_INV)||')')) AS IMAGE_KEY_INV_CNT , CASE WHEN COUNT(*) = 1 THEN MIN(B.DESCRIPTION) ELSE MIN(B.DESCRIPTION) || ' 외 ' || (COUNT(*)-1) || '건' END AS DESCRIPTION_INFO ,MAX(DECODE(C.PROCESS_TYPE, '0', '직납', '2', 'TR(' || (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = NVL((SELECT DELY_TO_CENTER FROM SUPLINFO2 WHERE SUPPLIER = E.AGENT), C.WAREHOUSE_CODE)) || ')' , ' ')) AS PROCESS_TYPE_TEXT ,MAX(NVL(B.AP_BILL_FLAG,'N')) AS AP_BILL_FLAG FROM ICOMIVHD A , ICOMIVDT B , ICOMPODT C,ICOMPOHD E, (SELECT CODE, TEXT5 AS INV_NO_URL FROM ICOMCOD1 WHERE TYPE = 'C019') D WHERE A.AGENT = #{st_com_code} AND A.INV_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND A.INV_NO LIKE UPPER('%'||TRIM(#{st_inv_no})||'%')
AND (C.PO_NO IN
UPPER(#{item})
OR C.LEGACY_PO_NO IN
UPPER(#{item})
)
AND E.DOC_TYPE = #{st_bfre_stck_yn}
AND E.DOC_TYPE != 'S'
AND A.PARCEL_INV_NO LIKE '%'||TRIM(#{st_parcel_inv_no})||'%'
AND A.PARCEL_YN = #{st_parcel_type}
AND A.PARCEL_COM_CODE = #{st_parcel_com_code}
AND A.IMAGE_KEY_INV IS NOT NULL
AND A.IMAGE_KEY_INV IS NULL
AND B.DELIVERY_DATE IS NOT NULL AND A.BUYER = B.BUYER AND A.INV_NO = B.INV_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ = C.PO_SEQ AND C.BUYER = E.BUYER AND C.PO_NO = E.PO_NO AND A.PARCEL_COM_CODE = D.CODE (+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' GROUP BY B.INV_NO,B.DS_DATE,B.PO_NO ORDER BY INVOICE_DATE DESC,DELIVERY_DATE DESC , BUYER_NAME, PO_NO )X WHERE 1=1
AND REPLACE(UPPER(X.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'

mapper.update:

/*updateDeliveryRecordDeleteIvdt_v2*/
UPDATE ICOMIVDT
SET
	  DELIVERY_QTY  = 0
	, DELIVERY_DATE = NULL
	, DELIVERY_ADD_DATE = NULL
	, DELIVERY_ADD_USER_ID = NULL
WHERE 
		BUYER   = #{buyer}
	AND INV_NO  = #{inv_no}
	AND INV_SEQ = #{inv_seq}
	AND STATUS != 'D'
